<?php
declare(strict_types=1);require_once __DIR__.'/common.php';
if(($_SERVER['REQUEST_METHOD']??'')!=='POST')fb_out(false,'Only POST requests are allowed.',['code'=>'METHOD_NOT_ALLOWED'],405);$pdo=fb_pdo();fb_schema($pdo);$in=fb_in();$token=trim((string)($in['token']??''));$action=strtolower(fb_clean($in['action']??'',20));if($token===''||!in_array($action,['solve','close','reopen'],true))fb_out(false,'Invalid ticket action.',['code'=>'INVALID_ACTION'],422);$ticket=fb_access($pdo,$token);if(!$ticket)fb_out(false,'Invalid support link.',['code'=>'INVALID_TICKET_LINK'],404);$auth=fb_authorized($pdo,$ticket);if(!$auth['ok'])fb_out(false,'Verification is required.',['code'=>'VERIFICATION_REQUIRED','verification_required'=>$auth['reason']],403);$id=(int)$ticket['ticket_id'];if($action==='solve'){$pdo->prepare("UPDATE support_tickets SET status='solved',solved_at=COALESCE(solved_at,CURRENT_TIMESTAMP),close_at=DATE_ADD(CURRENT_TIMESTAMP,INTERVAL 48 HOUR),closed_at=NULL,reminder_24_sent=0,reminder_12_sent=0,reminder_1_sent=0 WHERE id=:id LIMIT 1")->execute([':id'=>$id]);$msg='The ticket was marked solved and will close after 48 hours unless reopened.';}elseif($action==='reopen'){$pdo->prepare("UPDATE support_tickets SET status='awaiting_admin',solved_at=NULL,closed_at=NULL,close_at=NULL,last_message_at=CURRENT_TIMESTAMP WHERE id=:id LIMIT 1")->execute([':id'=>$id]);$msg='The ticket was reopened for support.';}else{$pdo->prepare("UPDATE support_tickets SET status='closed',closed_at=CURRENT_TIMESTAMP,close_at=NULL WHERE id=:id LIMIT 1")->execute([':id'=>$id]);$msg='The support conversation has been closed.';}fb_out(true,$msg,['status'=>$action==='solve'?'solved':($action==='reopen'?'awaiting_admin':'closed')]);
